    FE(["Ik","neem","de","verantwoordelijkheid","en","zet","het","vandaag","rechtgezet."], 8, "recht", "Presente: zet … recht.", ["v-rechtzetten"]),
    FB("Zo ___ we dat het nog eens gebeurt.", ["voorkomen"], "Evitamos.", ["v-voorkomen"], choices=["voorkomen","rechtzetten","toegeven"], tr="Assim evitamos que volte a acontecer."),
