    LI("Dat is mijn fout, en ik bied u mijn excuses aan.", ["Dat is mijn fout, en ik bied u mijn excuses aan","Dat is mijn fout en ik bied u mijn excuses aan"], "A culpa é minha e peço-lhe desculpa.", "Assumir.", ["v-excuses-aanbieden"]),
    WO("Admito o erro.", ["Ik","geef","de","fout","toe"], "Separável.", ["v-fout-toegeven"]),
    AR("fout","o erro","de", "De fout.", ["v-fout-toegeven"]),
